export type RuntimeEnvironment = {
  nodeEnv: 'development' | 'test' | 'production';
  port: number;
  databaseUrl: string;
  reportTimezone: string;
};

export function loadEnvironment(): RuntimeEnvironment {
  const nodeEnv = (process.env.NODE_ENV ?? 'development') as RuntimeEnvironment['nodeEnv'];

  if (!['development', 'test', 'production'].includes(nodeEnv)) {
    throw new Error(`Unsupported NODE_ENV value: ${nodeEnv}`);
  }

  const port = Number(process.env.PORT ?? 3000);
  if (!Number.isInteger(port) || port <= 0) {
    throw new Error('PORT must be a positive integer.');
  }

  const databaseUrl = process.env.DATABASE_URL ?? 'postgresql://postgres:postgres@localhost:5432/delivery_risk_dev';
  const reportTimezone = process.env.REPORT_TIMEZONE ?? 'Asia/Kolkata';

  return {
    nodeEnv,
    port,
    databaseUrl,
    reportTimezone,
  };
}
